const main=document.querySelector('#main');
const theme=document.querySelector('#theme');
const $=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el};
const el=(tag,cls,text,parent)=>{const node=$(tag,cls,text);parent?.append(node);return node};
const button=(label,cls,fn)=>{const b=$('button',cls,label);b.type='button';b.addEventListener('click',fn);return b};
const params=()=>new URLSearchParams(location.hash.split('?')[1]||'');
const catalogUrl=(p)=>`#/${p.toString()?'?'+p.toString():''}`;
function setTheme(value){document.documentElement.dataset.theme=value;theme.textContent=value==='dark'?'☼':'☾';theme.setAttribute('aria-label',`Switch to ${value==='dark'?'light':'dark'} theme`);try{localStorage.setItem('fieldnotes-theme',value)}catch{}}
try{if(localStorage.getItem('fieldnotes-theme')==='light')setTheme('light')}catch{}
theme.addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));
function notify(message){const toast=document.querySelector('#toast');toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2400)}
function update(p){history.replaceState(null,'',catalogUrl(p));renderCatalog(false)}
const stopwords=new Set(['i','me','a','an','the','for','to','of','in','on','with','need','want','find','show','please','skill','plugin','agent']);
function matches(item,p,omit){const terms=(p.get('q')||'').toLowerCase().trim().split(/\s+/).filter(t=>t&&!stopwords.has(t));const text=[item.name,item.description,item.body,item.type,item.owner,...item.files].join(' ').toLowerCase();return terms.every(t=>text.includes(t))&&['type','platform','category','status'].every(k=>k===omit||!p.get(k)||item[k]===p.get(k))}
function filterGroup(parent,title,key,values,p){const group=el('fieldset','filter-group',undefined,parent);el('legend','',title.toUpperCase(),group);for(const value of values){const label=el('label','filter-option',undefined,group);const input=el('input','',undefined,label);input.type='radio';input.name=key;input.checked=p.get(key)===value;input.addEventListener('change',()=>{p.set(key,value);update(p)});el('span','',value,label);el('span','',String(entries.filter(i=>i[key]===value).length).padStart(2,'0'),label)}}
function card(item,p){const a=$('a','card');a.href=`#/artifact/${encodeURIComponent(item.id)}?${p.toString()}`;const top=el('div','card-top',undefined,a);el('span','type-icon',item.icon,top);el('span','card-arrow','↗',top);el('h3','',item.name,a);el('p','',item.description,a);const badges=el('div','badges',undefined,a);el('span','badge type',item.type.toUpperCase(),badges);el('span','badge',item.platform,badges);el('span','badge',item.status,badges);if(p.get('q'))el('div','match',`MATCHES · ${item.files.join(' · ')}`,a);const foot=el('div','card-foot',undefined,a);el('span','',item.owner,foot);el('span','',item.version==='Not specified'?'VERSION UNKNOWN':`v${item.version}`,foot);return a}
function renderCatalog(focus=true){const p=params(),q=p.get('q')||'';const selected=entries.filter(i=>matches(i,p));main.replaceChildren();const wrap=el('div','wrap',undefined,main);const hero=el('section','hero',undefined,wrap);const intro=el('div','',undefined,hero);el('div','eyebrow','A LITTLE MORE CLARITY FOR YOUR WORKFLOW',intro);const h=el('h1','',undefined,intro);h.append('Find your next',document.createElement('br'));el('em','', 'better workflow.',h);el('p','', 'A considered collection of tools, skills, and agents for the work you do every day.',intro);const aside=el('div','hero-right',undefined,hero);el('strong','','BUILT FOR CURIOSITY. MADE FOR WORK.',aside);el('p','','Explore reusable building blocks for your AI tools. Find what fits, understand how it works, and make it your own.',aside);const stats=el('div','stats',undefined,aside);for(const [n,l] of [['06','EXAMPLES'],['03','ARTIFACT TYPES*'],['01','PLACE TO EXPLORE']]){const s=el('div','stat',undefined,stats);el('strong','',n,s);el('span','',l,s)}el('p','tiny','* Plus an MCP example. All entries are illustrative.',aside);
const catalog=el('section','catalog',undefined,wrap);catalog.id='catalog';const heading=el('div','catalog-head',undefined,catalog);const head=el('div','',undefined,heading);el('div','section-kicker','THE COLLECTION / 01',head);el('h2','','Explore the catalog',head);el('p','','A little less searching. A lot more doing.',heading);const search=el('label','search-box',undefined,catalog);el('span','search-icon','⌕',search).setAttribute('aria-hidden','true');const input=el('input','',undefined,search);input.type='search';input.placeholder='Search by task, tool, or keyword...';input.setAttribute('aria-label','Search the catalog');input.value=q;el('kbd','','/',search);input.addEventListener('input',()=>{const position=input.selectionStart;p.delete('q');if(input.value)p.set('q',input.value);history.replaceState(null,'',catalogUrl(p));renderCatalog(false);const next=document.querySelector('input[type=search]');next.focus();try{next.setSelectionRange(position,position)}catch{}});const examples=el('div','examples',undefined,catalog);el('span','example-label','TRY SEARCHING',examples);for(const query of ['API review','test coverage','architecture'])examples.append(button(query,'chip',()=>{p.set('q',query);update(p)}));const layout=el('div','catalog-layout',undefined,catalog);const filters=el('aside','filters',undefined,layout);filters.setAttribute('aria-label','Catalog filters');const fh=el('div','filter-heading',undefined,filters);el('strong','label','FILTER BY',fh);fh.append(button('Reset filters','text-button',()=>{for(const k of ['type','platform','category','status'])p.delete(k);update(p)}));filterGroup(filters,'Type','type',['Plugin','Skill','Agent','MCP'],p);filterGroup(filters,'Platform','platform',['Claude Code','Codex'],p);filterGroup(filters,'Use case','category',['Review','Testing','Planning','Research'],p);filterGroup(filters,'Support','status',['Verified','Author-reported','Not verified'],p);
const results=el('div','results',undefined,layout);const rh=el('div','results-head',undefined,results);const count=el('span','count',`${String(selected.length).padStart(2,'0')} RESULTS`,rh);count.setAttribute('role','status');el('span','sort',q?'Matching keywords':'Sorted by collection',rh);const grid=el('div','grid',undefined,results);if(selected.length)selected.forEach(i=>grid.append(card(i,p)));else{const empty=el('div','empty',undefined,grid);el('div','empty-symbol','⌕',empty);el('h3','','Nothing found just yet.',empty);el('p','',q?'Try a different keyword or clear your filters.':'No examples match the selected filters.',empty);empty.append(button('Clear search & filters','secondary',()=>update(new URLSearchParams())))}if(focus)main.focus({preventScroll:true})}
function renderDetail(id){const p=params(),item=entries.find(x=>x.id===id);main.replaceChildren();const wrap=el('div','wrap detail',undefined,main);const back=el('a','back','← Back to catalog',wrap);back.href=catalogUrl(p);if(!item){const e=el('div','empty',undefined,wrap);el('h3','','Artifact not found',e);el('p','','This example may have been removed or the link is incorrect.',e);return}const header=el('div','detail-header',undefined,wrap);const left=el('div','',undefined,header);el('div','section-kicker',`${item.type.toUpperCase()} / PROTOTYPE EXAMPLE`,left);el('h1','detail-title',item.name,left);el('p','',item.description,left);const source=el('a','secondary','View repository ↗',header);source.href='https://github.com/Artyem-Y/ai-marketplace';source.target='_blank';source.rel='noopener noreferrer';const layout=el('div','detail-layout',undefined,wrap);const content=el('div','',undefined,layout);let section=el('section','content-section',undefined,content);el('h2','','What it does',section);el('p','',item.body,section);el('div','notice','Demonstration content only. This artifact and its installation instructions are not available in the marketplace.',section);section=el('section','content-section',undefined,content);el('h2','','Platform compatibility',section);const row=el('div','platform-row',undefined,section);for(const platform of ['Claude Code','Codex']){const box=el('div','platform-card',undefined,row);el('strong','',platform,box);el('span','',platform===item.platform?item.status.toUpperCase():'NOT VERIFIED',box)}section=el('section','content-section',undefined,content);el('h2','','Usage',section);el('p','','No verified installation command is available for this example.',section);section=el('section','content-section',undefined,content);el('h2','','Access & requirements',section);el('p','',item.access,section);section=el('section','content-section',undefined,content);el('h2','','Related components',section);if(item.related.length){for(const id of item.related){const rel=entries.find(x=>x.id===id);if(rel){const a=el('a','related-link',`${rel.type}  /  ${rel.name}  ↗`,section);a.href=`#/artifact/${id}?${p.toString()}`}}}else el('p','','No related components specified.',section);section=el('section','content-section',undefined,content);el('h2','','Source files',section);item.files.forEach(file=>el('p','tiny',file,section));const side=el('aside','side-panel',undefined,layout);el('h3','','At a glance',side);for(const [k,v] of [['TYPE',item.type],['OWNER',item.owner],['VERSION',item.version],['USE CASE',item.category],['VERIFICATION','Demo only']]){const r=el('div','meta-row',undefined,side);el('span','meta-label',k,r);el('span','',v,r)}main.focus({preventScroll:true})}
function render(){const match=location.hash.match(/^#\/artifact\/([^?]+)/);if(match){try{renderDetail(decodeURIComponent(match[1]))}catch{renderDetail('')}}else renderCatalog()}
window.addEventListener('hashchange',render);document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!location.hash.includes('/artifact/')){e.preventDefault();document.querySelector('input[type=search]')?.focus()}});render();
